import{seeded as h}from"./city.min.js";export const CLOUDS={altitude:2800,span:24e4,tile:14e3,size:1024,cells:22,seed:20260925};export function cloudPuffs(f=CLOUDS){const o=h(f.seed),u=[];for(let e=0;e<f.cells;e++){const t=o(),n=o(),r=.03+o()*.05,l=10+Math.floor(o()*16);for(let s=0;s<l;s++){const c=o()*Math.PI*2,a=Math.sqrt(o()),i=t+Math.cos(c)*a*r*1.8,p=n+Math.sin(c)*a*r,d=r*(.35+o()*.4)*(1-a*.4);u.push([(i%1+1)%1,(p%1+1)%1,d,.55+o()*.35])}}return u}export function wrappedPuffs(f){const o=[];for(const[u,e,t,n]of f)for(const r of[-1,0,1])for(const l of[-1,0,1]){const s=u+r,c=e+l;s+t<0||s-t>1||c+t<0||c-t>1||o.push([s,c,t,n])}return o}export function cloudCover(f,o=64){const u=wrappedPuffs(f);let e=0;for(let t=0;t<o;t++)for(let n=0;n<o;n++){const r=(n+.5)/o,l=(t+.5)/o;u.some(([s,c,a])=>Math.hypot(r-s,l-c)<a)&&e++}return e/(o*o)}
